def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    x_best = np.zeros(dim)
    f_best = float('inf')
    history = []

    for i in range(budget):
        x_new = x_best + rng.normal(size=dim) * 0.5
        x_new = clip(x_new)
        f_new = func(x_new)

        if f_new < f_best:
            f_best = f_new
            x_best = x_new

        history.append((x_new, f_new))

    return x_best
